const results = items[0].json.places || [];
const searchQuery = items[0].json.searchParameters?.q || '';
const category = $('Search Query List').item.json.category;
const priority = $('Search Query List').item.json.priority;

if (results.length === 0) {
  return [];
}

// Process each result
const processed = results.map((place, index) => {
  // Extract phone number (clean format)
  let phone = place.phoneNumber || place.phone || '';

  // Extract website
  let website = place.website || '';

  // Generate prospect ID
  const prospectId = `PEL-LEAD-${Date.now()}-${index}`;

  return {
    json: {
      prospectId: prospectId,
      companyName: place.title || place.name || 'Unknown',
      businessType: place.type || category,
      phone: phone,
      address: place.address || '',
      city: place.city || extractCity(place.address),
      website: website,
      googleRating: place.rating || 0,
      reviewsCount: place.reviews || 0,
      description: place.description || '',
      latitude: place.latitude || '',
      longitude: place.longitude || '',
      leadSource: `Google Maps - ${searchQuery}`,
      opportunityScore: priority,
      timestamp: new Date().toISOString()
    }
  };
});

// Helper function to extract city from address
function extractCity(address) {
  if (!address) return 'Lagos';
  if (address.includes('Lagos')) return 'Lagos';
  if (address.includes('Abuja')) return 'Abuja';
  if (address.includes('Port Harcourt')) return 'Port Harcourt';
  return 'Nigeria';
}

return processed;

const newProspects = $('Process Serper Results').all();
const existingProspects = $('Get Existing Prospects').all();

// Get list of existing company names (lowercase for comparison)
const existingNames = existingProspects.map(item => 
  (item.json['Company Name'] || '').toLowerCase().trim()
);

// Filter out duplicates and clean data
const uniqueProspects = newProspects.filter(prospect => {
  const companyName = (prospect.json.companyName || '').toLowerCase().trim();

  // Skip if company name is empty or already exists
  if (!companyName || companyName === 'unknown') return false;
  if (existingNames.includes(companyName)) return false;

  return true;
}).map(prospect => {
  // Clean phone number format
  let phone = prospect.json.phone;
  if (phone) {
    // Remove spaces, dashes, parentheses
    phone = phone.replace(/[\s\-\(\)]/g, '');
    // Ensure it starts with +234
    if (phone.startsWith('0')) {
      phone = '+234' + phone.substring(1);
    } else if (!phone.startsWith('+')) {
      phone = '+234' + phone;
    }
  }

  return {
    json: {
      ...prospect.json,
      phone: phone,
      email: '', // Will be enriched later
      contactPerson: '' // Will be enriched later
    }
  };
});

// Return only unique new prospects
return uniqueProspects;

