// Find matching prospect
const matchedProspect = prospects.find(p => {
  const prospectEmail = (p.json.Email || '').toLowerCase();
  return fromEmail.includes(prospectEmail) || prospectEmail.includes(fromEmail);
});

if (!matchedProspect) {
