const negativeKeywords = ['not interested', 'no thanks', 'remove', 'unsubscribe', 'stop'];

const bodyLower = emailBody.toLowerCase();
const isPositive = positiveKeywords.some(keyword => bodyLower.includes(keyword));
const isNegative = negativeKeywords.some(keyword => bodyLower.includes(keyword));

let sentiment = 'Neutral';
if (isPositive) sentiment = 'Positive';
if (isNegative) sentiment = 'Negative';

return {
  json: {
    prospectId: matchedProspect.json['Prospect ID'],
    companyName: matchedProspect.json['Company Name'],
    email: matchedProspect.json.Email,
    fromEmail: fromEmail,
    subject: emailSubject,
    body: emailBody,
    sentiment: sentiment,
    receivedAt: new Date().toISOString()
  }
