const today = new Date().toISOString().split('T')[0];
const prospects = items;

// Filter prospects that need follow-up today
const dueFollowUps = prospects.filter(item => {
  const followUpDate = item.json['Next Follow-up Date'];
  const status = item.json['Status'] || '';
  const responseReceived = item.json['Response Received'] || $input.first().json['Response Received'];
  const emailStage = parseInt(item.json['Email Sequence Stage'] || '0');

  // Skip if no follow-up date
  if (!followUpDate) return false;

  // Check if follow-up is due today
  const dueDate = new Date(followUpDate).toISOString().split('T')[0];

  // Only follow up if:
  // - Follow-up date is today or past
  // - Status is not Won/Lost/Not Interested
  // - No response received
  // - Email stage is less than 4 (max 3 follow-ups)

  return dueDate <= today && 
         !status.includes('Won') && 
         !status.includes('Lost') &&
         !status.includes('Not Interested') &&
         responseReceived === 'No' &&
         emailStage < 4;
});

if (dueFollowUps.length === 0) {
  console.log('No follow-ups due today');
  return [];
}

return dueFollowUps;

