const prospect = $('Filter Due Follow-ups').item.json;
const emailStage = parseInt(prospect['Email Sequence Stage'] || '1');
const companyName = prospect['Company Name'];
const businessType = prospect['Business Type'];

let subject = '';

// Dynamic subject lines based on follow-up stage
switch(emailStage) {
  case 1:
    // First follow-up (Day 3)
    const subjects1 = [
      `Quick follow-up - ${companyName}`,
      `Thought you might have missed this`,
      `${companyName} - Elevator solutions`,
      `Following up on my message`
    ];
    subject = subjects1[Math.floor(Math.random() * subjects1.length)];
    break;

  case 2:
    // Second follow-up (Day 7)
    const subjects2 = [
      `Success story for ${businessType} companies`,
      `How we helped similar ${businessType} businesses`,
      `${companyName} - Worth a conversation?`,
      `Case study: ${businessType} elevator project`
    ];
    subject = subjects2[Math.floor(Math.random() * subjects2.length)];
    break;

  case 3:
    // Final follow-up (Day 14)
    const subjects3 = [
      `Last note about ${companyName}'s elevator needs`,
      `Final follow-up - Free assessment offer`,
      `Should I close your file?`,
      `One last thing before I let you go`
    ];
    subject = subjects3[Math.floor(Math.random() * subjects3.length)];
    break;

  default:
    subject = `Following up - ${companyName}`;
}

return {
  json: {
    ...prospect,
    subject: subject
  }
};

const prospect = $('Generate Subject Line').item.json;
const currentStage = parseInt(prospect['Email Sequence Stage'] || '1');
const nextStage = currentStage + 1;

const today = new Date();
let nextFollowUpDate = null;

// Calculate next follow-up date based on stage
switch(nextStage) {
  case 2:
    // After first follow-up, wait 4 days
    nextFollowUpDate = new Date(today);
    nextFollowUpDate.setDate(today.getDate() + 4);
    break;
  case 3:
    // After second follow-up, wait 7 days
    nextFollowUpDate = new Date(today);
    nextFollowUpDate.setDate(today.getDate() + 7);
    break;
  case 4:
    // After third follow-up, wait 30 days (long-term nurture)
    nextFollowUpDate = new Date(today);
    nextFollowUpDate.setDate(today.getDate() + 30);
    break;
  default:
    // No more follow-ups after stage 4
    nextFollowUpDate = null;
}

return {
  json: {
    prospectId: prospect['Prospect ID'],
    emailSequenceStage: nextStage.toString(),
    lastContactDate: today.toISOString().split('T')[0],
    nextFollowupDate: nextFollowUpDate ? nextFollowUpDate.toISOString().split('T')[0] : '',
    status: nextStage > 3 ? 'Contacted - No Response (Archive)' : 'Contacted - Awaiting Response'
  }
};

// Get all the data from previous nodes
const dueFollowups = $('Filter Due Follow-ups').all();
const followupsSent = $('Send Follow-up Email').all();
const nextFollowupData = $('Calculate Next Follow-up').all();

// Count by stage
const stage1 = dueFollowups.filter(item => item.json['Email Sequence Stage'] === '1').length;
const stage2 = dueFollowups.filter(item => item.json['Email Sequence Stage'] === '2').length;
const stage3 = dueFollowups.filter(item => item.json['Email Sequence Stage'] === '3').length;

// Build the follow-ups table HTML
let followupsTableHTML = '';

nextFollowupData.forEach((item, index) => {
  const followupData = item.json;

  // Get corresponding prospect data from the workflow
  const prospectData = dueFollowups[index]?.json || {};
  const companyName = prospectData['Company Name'] || followupData.prospectId || $('Get All Prospects1').first().json['Company Name'];
  const firstContact = prospectData['First Contact Date'] || $('Get All Prospects1').first().json['First Contact Date'];
  const nextFollowup = followupData.nextFollowupDate || $input.first().json['Next Follow-up Date'];

  followupsTableHTML += `
    <tr>
      <td>${companyName}</td>
      <td>Stage ${followupData.emailSequenceStage}</td>
      <td>${firstContact}</td>
      <td>${nextFollowup}</td>
    </tr>
  `;
});

// Handle case where no follow-ups were sent
if (followupsTableHTML === '') {
  followupsTableHTML = `
    <tr>
      <td colspan="4" style="text-align: center; color: #999;">No follow-ups sent today</td>
    </tr>
  `;
}

// Build the complete HTML email
const htmlEmail = `
<h2>📧 Daily Follow-up Activity Report</h2>

<p><strong>Date:</strong> ${new Date().toLocaleDateString('en-US', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
})}</p>

<h3>Summary:</h3>
<ul>
  <li><strong>Follow-ups Sent Today:</strong> ${followupsSent.length}</li>
  <li><strong>Stage 1 (Day 3):</strong> ${stage1}</li>
  <li><strong>Stage 2 (Day 7):</strong> ${stage2}</li>
  <li><strong>Stage 3 (Day 14+):</strong> ${stage3}</li>
</ul>

<h3>Follow-ups Sent:</h3>
<table border="1" cellpadding="8" style="border-collapse: collapse; width: 100%;">
  <tr style="background-color: #f0f0f0;">
    <th>Company</th>
    <th>Email Stage</th>
    <th>First Contact</th>
    <th>Next Follow-up</th>
  </tr>
  ${followupsTableHTML}
</table>

<hr>
<p style="color: #666; font-size: 12px;">Check the CRM for complete prospect details.</p>
`;

return {
  json: {
    htmlEmail: htmlEmail,
    totalFollowups: followupsSent.length,
    stage1Count: stage1,
    stage2Count: stage2,
    stage3Count: stage3
  }
};

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}
const prospects = items;

// Date calculations
const today = new Date();
const sevenDaysAgo = new Date(today);
sevenDaysAgo.setDate(today.getDate() - 7);
const sevenDaysAgoStr = sevenDaysAgo.toISOString().split('T')[0];

// Initialize counters
const metrics = {
  totalProspects: prospects.length,
  newThisWeek: 0,
  highPriority: 0,
  mediumPriority: 0,
  lowPriority: 0,
  contacted: 0,
  responseReceived: 0,
  positiveResponses: 0,
  notInterested: 0,
  awaitingResponse: 0,
  byCity: {},
  byBusinessType: {},
  totalEstimatedValue: 0,
  averageResponseRate: 0
};

prospects.forEach(p => {
  const prospect = p.json;
  const firstContact = prospect['First Contact Date'] || '';
  const status = prospect['Status'] || '';
  const opportunityScore = prospect['Opportunity Score'] || '';
  const city = prospect['City'] || 'Unknown';
  const businessType = prospect['Business Type'] || 'Unknown';
  const estimatedValue = prospect['Estimated Value'] || '';
  const responseReceived = prospect['Response Received'] || 'No';

  // Count new prospects this week
  if (firstContact >= sevenDaysAgoStr) {
    metrics.newThisWeek++;
  }

  // Count by priority
  if (opportunityScore === 'HIGH') metrics.highPriority++;
  if (opportunityScore === 'MEDIUM') metrics.mediumPriority++;
  if (opportunityScore === 'LOW') metrics.lowPriority++;

  // Count by status
  if (status.includes('Contacted')) metrics.contacted++;
  if (responseReceived === 'Yes') metrics.responseReceived++;
  if (status.includes('Interested')) metrics.positiveResponses++;
  if (status.includes('Not Interested')) metrics.notInterested++;
  if (status.includes('Awaiting Response')) metrics.awaitingResponse++;

  // Group by city
  metrics.byCity[city] = (metrics.byCity[city] || 0) + 1;

  // Group by business type
  metrics.byBusinessType[businessType] = (metrics.byBusinessType[businessType] || 0) + 1;

  // Calculate estimated value (extract numbers from strings like "₦15M-₦30M")
  const valueMatch = estimatedValue.match(/₦(\d+)M/);
  if (valueMatch) {
    metrics.totalEstimatedValue += parseInt(valueMatch[1]) * 1000000;
  }
});

// Calculate response rate
if (metrics.contacted > 0) {
  metrics.averageResponseRate = ((metrics.responseReceived / metrics.contacted) * 100).toFixed(1);
}

// Sort cities and business types by count
const topCities = Object.entries(metrics.byCity)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5);

const topBusinessTypes = Object.entries(metrics.byBusinessType)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5);

return {
  json: {
    reportDate: today.toISOString().split('T')[0],
    metrics: metrics,
    topCities: topCities,
    topBusinessTypes: topBusinessTypes
  }
};
return $input.all();

